class Solution {
public:
    int finalPositionOfSnake(int n, vector<string>& commands) {
        int r = 0, c = 0;
        for (auto& s : commands) {
            if (s == "UP") r--; else if (s == "DOWN") r++;
            else if (s == "LEFT") c--; else c++;
        }
        return r * n + c;
    }
};

c.java:
class Solution {
    public int finalPositionOfSnake(int n, List<String> commands) {
        int r = 0, c = 0;
        for (String s : commands) {
            switch (s) {
                case "UP": r--; break;
                case "DOWN": r++; break;
                case "LEFT": c--; break;
                default: c++;
            }
        }
        return r * n + c;
    }
}

